$fFrom = $_GET['from'] ?? ''; $fTo = $_GET['to'] ?? ''; $fMethod = $_GET['metode'] ?? ''; $fStatus = $_GET['status'] ?? '';
$validDate = fn($d) => preg_match('/^\d{4}-\d{2}-\d{2}$/', $d) && strtotime($d) !== false;
$where = []; $params = [];
if ($validDate($fFrom)) { $where[] = 'o.created_at >= ?'; $params[] = $fFrom . ' 00:00:00'; } else { $fFrom = ''; }
if ($validDate($fTo)) { $where[] = 'o.created_at < DATE_ADD(?, INTERVAL 1 DAY)'; $params[] = $fTo; } else { $fTo = ''; }
if (isset($methodLabel[$fMethod])) { $where[] = 'o.metode_bayar = ?'; $params[] = $fMethod; } else { $fMethod = ''; }
if (isset($statusClass[$fStatus])) { $where[] = 'o.status = ?'; $params[] = $fStatus; } else { $fStatus = ''; }
$sql = 'SELECT o.*, u.nama_lengkap AS kasir FROM orders o JOIN users u ON u.id = o.user_id' . ($where ? ' WHERE ' . implode(' AND ', $where) : '') . ' ORDER BY o.created_at DESC, o.id DESC LIMIT 200';
$st = db()->prepare($sql); $st->execute($params); $orders = $st->fetchAll();
?>
